// Read-only research over public feeds already approved for the editorial pilot.
// Replayed or stale requests (older than 5 minutes) get an empty result.
const body = $input.first().json.body ?? {};
const ts = Date.parse(body.timestamp ?? '');
if (!ts || Math.abs(Date.now() - ts) > 300000) return [{ json: { items: [] } }];
const topic = String(body.input?.topic ?? '').toLowerCase().slice(0, 80);
const feeds = ['https://blog.n8n.io/rss/', 'https://blog.google/technology/ai/rss/', 'https://github.blog/feed/'];
const pages = await Promise.all(feeds.map(url => this.helpers.httpRequest({ url, method: 'GET', timeout: 3000, json: false }).catch(() => '')));
const items = [];
for (const xml of pages) for (const m of String(xml).matchAll(/<item>([\s\S]*?)<\/item>/g)) {
  const title = ((m[1].match(/<title>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/title>/) || [])[1] || '').trim();
  const url = ((m[1].match(/<link>([\s\S]*?)<\/link>/) || [])[1] || '').trim();
  if (title && url.startsWith('https://') && (!topic || title.toLowerCase().includes(topic))) items.push({ title: title.slice(0, 200), url, licensed: false });
}
return [{ json: { items: items.slice(0, 5) } }];
